mapper.select:
select
beautyProjects.*
from beauty_projects beautyProjects

    and beautyProjects.id = #{id}
    and beautyProjects.title like concat('%',#{title},'%')
    and beautyProjects.info = #{info}
    and beautyProjects.price = #{price}
    and beautyProjects.banner = #{banner}
    and beautyProjects.detail = #{detail}
    and beautyProjects.cover_img = #{coverImg}
    and beautyProjects.create_time = #{createTime}
    and beautyProjects.status = #{status}


    limit #{current},#{pageSize}

select count(*) from beauty_projects beautyProjects

    and beautyProjects.id = #{id}
    and beautyProjects.title like concat('%',#{title},'%')
    and beautyProjects.info = #{info}
    and beautyProjects.price = #{price}
    and beautyProjects.banner = #{banner}
    and beautyProjects.detail = #{detail}
    and beautyProjects.cover_img = #{coverImg}
    and beautyProjects.create_time = #{createTime}
    and beautyProjects.status = #{status}
